import { LazyCredential, type ResolvedAuth } from '@servicenow/sdk-api'
import type { SessionOrToken } from '../auth'

export function userSessionToCredential(session: SessionOrToken): LazyCredential {
    const instanceUrl = new URL(session.instanceUrl)
    const resolvedAuth: ResolvedAuth =
        session.type === 'oauth'
            ? { type: 'oauth', token: session.access_token }
            : { type: 'basic', token: session.userToken, cookie: getAuthCookie(session) }

    return new LazyCredential(instanceUrl, () => resolvedAuth)
}

export function getAuthCookie(auth: SessionOrToken) {
    if (auth.type === 'basic' && auth.cookie) {
        return auth.cookie.getCookieStringSync(auth.instanceUrl)
    }

    return undefined
}
